import { Component, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { NavbarComponent } from './components/navbar/navbar.component';
import { HeroComponent } from './components/hero/hero.component';
import { DivisionsShowcaseComponent } from './components/divisions-showcase/divisions-showcase.component';
import { ShipmentTrackerComponent } from './components/shipment-tracker/shipment-tracker.component';
import { RfqCalculatorComponent } from './components/rfq-calculator/rfq-calculator.component';
import { ComplianceCertificatesComponent } from './components/compliance-certificates/compliance-certificates.component';
import { AnalyticsDashboardComponent } from './components/analytics-dashboard/analytics-dashboard.component';
import { FooterComponent } from './components/footer/footer.component';

// Enterprise ERP Modules
import { RoleManagementComponent } from './components/role-management/role-management.component';
import { ProductManagementComponent } from './components/product-management/product-management.component';
import { SupplierManagementComponent } from './components/supplier-management/supplier-management.component';
import { ImportManagementComponent } from './components/import-management/import-management.component';
import { CustomsDocsComponent } from './components/customs-docs/customs-docs.component';
import { WarehouseInventoryComponent } from './components/warehouse-inventory/warehouse-inventory.component';
import { ExportManagementComponent } from './components/export-management/export-management.component';
import { AccountsCostingComponent } from './components/accounts-costing/accounts-costing.component';
import { ErpDashboardComponent } from './components/erp-dashboard/erp-dashboard.component';

export type ErpModuleTab = 
  | 'overview' 
  | 'roles' 
  | 'products' 
  | 'suppliers' 
  | 'imports' 
  | 'shipments' 
  | 'customs' 
  | 'warehouse' 
  | 'exports' 
  | 'accounts' 
  | 'reports';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [
    CommonModule,
    NavbarComponent,
    HeroComponent,
    DivisionsShowcaseComponent,
    ShipmentTrackerComponent,
    RfqCalculatorComponent,
    ComplianceCertificatesComponent,
    AnalyticsDashboardComponent,
    FooterComponent,
    RoleManagementComponent,
    ProductManagementComponent,
    SupplierManagementComponent,
    ImportManagementComponent,
    CustomsDocsComponent,
    WarehouseInventoryComponent,
    ExportManagementComponent,
    AccountsCostingComponent,
    ErpDashboardComponent
  ],
  template: `
    <div class="min-h-screen bg-slate-950 text-slate-100 flex flex-col selection:bg-emerald-500 selection:text-slate-950">

      <!-- Top Enterprise Navigation Header -->
      <app-navbar></app-navbar>

      <!-- Main Enterprise Module Selector Bar -->
      <nav class="bg-slate-900/90 border-b border-slate-800 backdrop-blur-md sticky top-[69px] z-40 px-4 py-2 overflow-x-auto">
        <div class="max-w-7xl mx-auto flex items-center gap-1 text-xs">

          <button 
            (click)="activeTab.set('overview')"
            [class]="activeTab() === 'overview' ? 'px-3 py-1.5 rounded-lg bg-emerald-500 text-slate-950 font-extrabold shadow transition' : 'px-3 py-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-slate-800 font-medium transition'">
            🌐 Overview Portal
          </button>

          <button 
            (click)="activeTab.set('roles')"
            [class]="activeTab() === 'roles' ? 'px-3 py-1.5 rounded-lg bg-emerald-500 text-slate-950 font-extrabold shadow transition' : 'px-3 py-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-slate-800 font-medium transition'">
            👥 Roles & Users
          </button>

          <button 
            (click)="activeTab.set('products')"
            [class]="activeTab() === 'products' ? 'px-3 py-1.5 rounded-lg bg-emerald-500 text-slate-950 font-extrabold shadow transition' : 'px-3 py-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-slate-800 font-medium transition'">
            📦 Product Master
          </button>

          <button 
            (click)="activeTab.set('suppliers')"
            [class]="activeTab() === 'suppliers' ? 'px-3 py-1.5 rounded-lg bg-emerald-500 text-slate-950 font-extrabold shadow transition' : 'px-3 py-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-slate-800 font-medium transition'">
            🏢 Suppliers & Buyers
          </button>

          <button 
            (click)="activeTab.set('imports')"
            [class]="activeTab() === 'imports' ? 'px-3 py-1.5 rounded-lg bg-emerald-500 text-slate-950 font-extrabold shadow transition' : 'px-3 py-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-slate-800 font-medium transition'">
            📥 Import PO & LC
          </button>

          <button 
            (click)="activeTab.set('shipments')"
            [class]="activeTab() === 'shipments' ? 'px-3 py-1.5 rounded-lg bg-emerald-500 text-slate-950 font-extrabold shadow transition' : 'px-3 py-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-slate-800 font-medium transition'">
            🚢 Vessel Shipments
          </button>

          <button 
            (click)="activeTab.set('customs')"
            [class]="activeTab() === 'customs' ? 'px-3 py-1.5 rounded-lg bg-emerald-500 text-slate-950 font-extrabold shadow transition' : 'px-3 py-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-slate-800 font-medium transition'">
            📑 Customs & Docs
          </button>

          <button 
            (click)="activeTab.set('warehouse')"
            [class]="activeTab() === 'warehouse' ? 'px-3 py-1.5 rounded-lg bg-emerald-500 text-slate-950 font-extrabold shadow transition' : 'px-3 py-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-slate-800 font-medium transition'">
            🏬 Warehouse Stock
          </button>

          <button 
            (click)="activeTab.set('exports')"
            [class]="activeTab() === 'exports' ? 'px-3 py-1.5 rounded-lg bg-emerald-500 text-slate-950 font-extrabold shadow transition' : 'px-3 py-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-slate-800 font-medium transition'">
            📤 Export Orders
          </button>

          <button 
            (click)="activeTab.set('accounts')"
            [class]="activeTab() === 'accounts' ? 'px-3 py-1.5 rounded-lg bg-emerald-500 text-slate-950 font-extrabold shadow transition' : 'px-3 py-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-slate-800 font-medium transition'">
            💰 Accounts & Costing
          </button>

          <button 
            (click)="activeTab.set('reports')"
            [class]="activeTab() === 'reports' ? 'px-3 py-1.5 rounded-lg bg-emerald-500 text-slate-950 font-extrabold shadow transition' : 'px-3 py-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-slate-800 font-medium transition'">
            📊 Executive Reports
          </button>

        </div>
      </nav>

      <!-- Active Module Workspace -->
      <main class="flex-grow">
        @if (activeTab() === 'overview') {
          <app-hero></app-hero>
          <app-divisions-showcase></app-divisions-showcase>
          <app-shipment-tracker></app-shipment-tracker>
          <app-rfq-calculator></app-rfq-calculator>
          <app-compliance-certificates></app-compliance-certificates>
          <app-analytics-dashboard></app-analytics-dashboard>
        }

        <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          @if (activeTab() === 'roles') {
            <app-role-management></app-role-management>
          }
          @if (activeTab() === 'products') {
            <app-product-management></app-product-management>
          }
          @if (activeTab() === 'suppliers') {
            <app-supplier-management></app-supplier-management>
          }
          @if (activeTab() === 'imports') {
            <app-import-management></app-import-management>
          }
          @if (activeTab() === 'shipments') {
            <app-shipment-tracker></app-shipment-tracker>
          }
          @if (activeTab() === 'customs') {
            <app-customs-docs></app-customs-docs>
          }
          @if (activeTab() === 'warehouse') {
            <app-warehouse-inventory></app-warehouse-inventory>
          }
          @if (activeTab() === 'exports') {
            <app-export-management></app-export-management>
          }
          @if (activeTab() === 'accounts') {
            <app-accounts-costing></app-accounts-costing>
          }
          @if (activeTab() === 'reports') {
            <app-erp-dashboard></app-erp-dashboard>
          }
        </div>
      </main>

      <app-footer></app-footer>
    </div>
  `
})
export class AppComponent {
  activeTab = signal<ErpModuleTab>('overview');
}
